 static object Get(object o,string n)=>o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance)?.GetValue(o);static bool Active=>view!=null&&(bool)Get(view,"passerActive");static void Check(bool v,string m){if(!v)throw new Exception(m);checks.Add(m);Debug.Log("WILDLIFE_NPC_PASS "+m);}static Button B(string n)=>Object.FindObjectsByType<Button>(FindObjectsSortMode.None).FirstOrDefault(b=>b.name==n&&b.IsInteractable());static void Key(bool down){if(Keyboard.current==null)InputSystem.AddDevice<Keyboard>();InputSystem.QueueStateEvent(Keyboard.current,down?new KeyboardState(UnityEngine.InputSystem.Key.S):new KeyboardState());InputSystem.Update();}
 public static void Run(bool skip){if(!Path.IsPathRooted(D)||!Directory.Exists(D))throw new InvalidOperationException("Create the isolated output directory first.");if(PlayerSettings.companyName!="BatterMapValidation"||EditorApplication.isPlaying)throw new Exception("isolated/off only");SessionState.SetBool("WildlifeNpcQA",true);SessionState.SetBool("WildlifeNpcQA.Skip",skip);EditorSceneManager.OpenScene(TitleSceneController.ScenePath);EditorApplication.isPlaying=true;}
 [InitializeOnLoadMethod]static void Resume(){if(!SessionState.GetBool("WildlifeNpcQA",false))return;skipRun=SessionState.GetBool("WildlifeNpcQA.Skip",false);next=EditorApplication.timeSinceStartup+2;end=next+140;EditorApplication.update+=Tick;Application.logMessageReceived+=Log;Application.runInBackground=true;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();}
