 static void Tick(){EditorApplication.QueuePlayerLoopUpdate();if(!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+.07;try{if(EditorApplication.timeSinceStartup>end)throw new Exception("timeout phase="+step);view=StoryTutorial.Instance?.GetComponent<StoryTutorialView>();if(Active){var w=(Image)Get(view,"walker");if(w.sprite!=null)frames.Add(w.sprite.name);if(Get(view,"passerCoin") is Image)seenCoin=true;if(Get(view,"passerSword") is Image)seenHeld=true;}switch(step){
 case 0:var title=Object.FindFirstObjectByType<TitleSceneController>();if(title==null)return;((Button)Get(title,"startButton")).onClick.Invoke();step=1;next+=.3;break;
