 case 2:if(!Active){Next();return;}Check(((Image)Get(view,"walker")).rectTransform.localScale.x<0,"actual intro passer faces its leftward path");Check(SmithingLoop.Instance.Campaign.gold==0,"no coin credited before presentation completes");start=EditorApplication.timeSinceStartup;if(skipRun){step=8;}else step=3;break;
