 case 10:if(SmithingLoop.Instance.Campaign.story.safeScene<4){Next();return;}Check(!Active&&Get(view,"passerCoin")==null&&Get(view,"passerSword")==null,"real story skip cleans temporary NPC cue");Check(SmithingLoop.Instance.Campaign.story.applied.Count(x=>x=="intro-coin")<=1,"skip cannot duplicate coin grant");Finish(true,"Real StorySkip/confirmation during NPC coin phase reaches scene4 via existing logo policy; intro skip reward policy preserved.");break;
 }}catch(Exception e){Finish(false,e.ToString());}}
 static void Finish(bool pass,string m){Key(false);SessionState.SetBool("WildlifeNpcQA",false);EditorApplication.update-=Tick;Application.logMessageReceived-=Log;File.WriteAllText(D+(skipRun?"/npc-skip.json":"/npc-normal.json"),JsonUtility.ToJson(new R{passed=pass&&errors.Count==0,message=m,checks=checks.ToArray(),errors=errors.ToArray(),frames=frames.ToArray()},true));EditorApplication.isPlaying=false;}[Serializable]class R{public bool passed;public string message;public string[] checks,errors,frames;}
